const CACHE='joseki-sage-v5';
const ICONS={
  'icon-192.png':    '',
  'icon-192m.png':   '',
  'icon-512.png':    '',
  'icon-512m.png':   '',
  'icon-splash.png': '',
};

function iconResponse(b64){
  var bin=atob(b64),buf=new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++)buf[i]=bin.charCodeAt(i);
  return new Response(buf,{status:200,headers:{'Content-Type':'image/png','Cache-Control':'public,max-age=31536000'}});
}

self.addEventListener('install',function(event){
  event.waitUntil(
    caches.open(CACHE).then(function(cache){
      var base=self.registration.scope;
      Object.keys(ICONS).forEach(function(name){
        cache.put(new Request(base+name),iconResponse(ICONS[name]));
      });
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate',function(event){
  event.waitUntil(self.clients.claim());
});

self.addEventListener('fetch',function(event){
  var name=new URL(event.request.url).pathname.split('/').pop();
  if(ICONS[name]){
    event.respondWith(caches.match(event.request).then(function(r){
      return r||iconResponse(ICONS[name]);
    }));
    return;
  }
  event.respondWith(
    fetch(event.request).then(function(response){
      var clone=response.clone();
      caches.open(CACHE).then(function(cache){cache.put(event.request,clone);});
      return response;
    }).catch(function(){
      return caches.match(event.request);
    })
  );
});
